mod solution;

fn main() {
    let cases = [
    (r#"[(2,a),(1,x),(2,b),(1,y)]"#, r#"1x,1y,2a,2b"#),
    (r#"[(1,b),(1,a),(0,z)]"#, r#"0z,1b,1a"#),
    (r#"
[(1,b),(1,a),(0,z)]
"#, r#"0z,1b,1a"#),
    (r#"  
[(2,a),(1,x),(2,b),(1,y)]
  "#, r#"1x,1y,2a,2b"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS merge-sort");
}
